import { registerFetcher } from 'qortex-core';

registerFetcher('users', async () => {
  const res = await fetch('/api/users');
  return res.json();
});

import { fetchQuery } from 'qortex-core';

// Fetches and caches
const users = await fetchQuery('users');

// Subsequent calls return cached data instantly
const cachedUsers = await fetchQuery('users');

import { subscribeQuery } from 'qortex-core';

const unsubscribe = subscribeQuery('users', (data) => {
  console.log('Users updated:', data);
});
